import React, { useEffect, useState } from "react";
import {
  MapContainer,
  TileLayer,
  CircleMarker,
  Popup,
  Circle,
  useMap,
  GeoJSON, // 👈 ¡Esta importación faltaba!
} from "react-leaflet";
import "leaflet/dist/leaflet.css";

// Componente para cambiar la vista del mapa al seleccionar un sismo
const ChangeView = ({ coordenadas }) => {
  const map = useMap();
  useEffect(() => {
    if (coordenadas) {
      map.setView([coordenadas.lat, coordenadas.lng], 7);
    }
  }, [coordenadas, map]);
  return null;
};

// 👈 AGREGAR el prop 'placas' aquí
const MapaMexico = ({ coordenadas, theme, placas }) => {
  const [circleScale, setCircleScale] = useState(1);
  const [opacity, setOpacity] = useState(0.6);

  // 👈 AGREGAR debug para ver las placas
  useEffect(() => {
    console.log("MapaMexico recibió placas:", placas);
    console.log("Cantidad de placas:", placas?.length);
    if (placas && placas.length > 0) {
      console.log("Primera placa:", placas[0]);
    }
  }, [placas]);

  // Animación del círculo
  useEffect(() => {
    if (!coordenadas) return;

    let scale = 1;
    let opac = 0.6;

    const interval = setInterval(() => {
      scale += 0.05;
      opac = Math.max(opac - 0.01, 0);

      setCircleScale(scale);
      setOpacity(opac);

      if (scale > 3 || opac <= 0) {
        scale = 1;
        opac = 0.6;
      }
    }, 50);

    return () => clearInterval(interval);
  }, [coordenadas]);

  // Elegir capa del mapa según el tema
  const tileLayerURL =
    theme === "dark"
      ? "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
      : "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png";

  const tileLayerAttribution =
    theme === "dark"
      ? '&copy; <a href="https://carto.com/">CARTO</a>'
      : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

  // 👈 AGREGAR función para manejar cada placa
  const onEachFeature = (feature, layer) => {
    if (feature.properties) {
      layer.bindPopup(`
        <div>
          <h3>${feature.properties.nombre || 'Placa Tectónica'}</h3>
          <p>${feature.properties.descripcion || 'Sin descripción'}</p>
        </div>
      `);
    }
  };

  // 👈 AGREGAR estilos para las placas
  const placaStyle = {
    color: "#9abf8f",
    weight: 2,
    opacity: 0.2,
    fillOpacity: 0.1,
    fillColor: "#b3dda6"
  };

  return (
    <div style={{ position: 'relative', height: "100%", width: "100%" }}>
      {/* 👈 AGREGAR indicador de debug */}
      

      <MapContainer
        center={[23.6345, -102.5528]} // Centro de México
        zoom={5}
        style={{ height: "100%", width: "100%" }}
      >
        <TileLayer 
          url={tileLayerURL} 
          attribution={tileLayerAttribution} 
          noWrap={true} 
        />
        
        {/* 👈 AGREGAR renderizado de placas */}
        {placas && placas.length > 0 && placas.map((placa, index) => {
          console.log(`Renderizando placa ${index}:`, placa.properties?.nombre);
          
          try {
            return (
              <GeoJSON
                key={`placa-${index}-${placa.properties?.id || Math.random()}`}
                data={placa}
                style={placaStyle}
                onEachFeature={onEachFeature}
              />
            );
          } catch (error) {
            console.error(`Error renderizando placa ${index}:`, error, placa);
            return null;
          }
        })}

        <ChangeView coordenadas={coordenadas} />
        
        {coordenadas && (
          <>
            <CircleMarker
              center={[coordenadas.lat, coordenadas.lng]}
              radius={10}
              color="red"
              fillColor="red"
              fillOpacity={0.8}
            >
              <Popup>
                <b>Ubicación del Sismo</b> <br />
                Lat: {coordenadas.lat}, Lng: {coordenadas.lng}
              </Popup>
            </CircleMarker>
            <Circle
              center={[coordenadas.lat, coordenadas.lng]}
              radius={circleScale * 50000}
              color="red"
              fillColor="red"
              fillOpacity={opacity}
              stroke={false}
            />
          </>
        )}
      </MapContainer>
    </div>
  );
};

export default MapaMexico;
